import { chromium } from 'playwright';
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
const root = process.argv[2];
const files = readdirSync(root, { recursive: true }).filter((f) => f.endsWith('.png')).map((f) => join(root, f));
const b = await chromium.launch(); const p = await b.newPage();
for (const f of files) {
  const out = await p.evaluate(async (src) => { const img = new Image(); img.src = src; await img.decode();
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height; const g = c.getContext('2d'); g.drawImage(img, 0, 0);
    g.fillStyle = '#000'; g.fillRect(8, 8, 336, 22); g.fillStyle = '#fff'; g.font = '12px monospace'; g.fillText('table •••••••••• (room code removed)', 17, 24);
    return c.toDataURL('image/png').split(',')[1]; }, 'data:image/png;base64,' + readFileSync(f).toString('base64'));
  writeFileSync(f, Buffer.from(out, 'base64'));
}
console.log('redacted', files.length); await b.close();
EOF
